// PRIORITY IS SET BY RULES HERE, NOT BY THE AI.
// P1: blocks work or hits customers/revenue AND needed within 14 days
// P2: blocks work or hits customers/revenue, OR needed within 14 days
// P3: everything else
const f = $('Settings').first().json;
const existing = $input.all().map(i => i.json).filter(r => r && r.title)
  .map(r => ({ title: r.title, status: r.status, routed_to: r.routed_to }));
const serious = f.impact === 'Blocks our work' || f.impact === 'Affects customers or revenue';
let daysLeft = null;
if (f.neededBy) {
  const today = new Date(); today.setHours(0, 0, 0, 0);
  daysLeft = Math.round((new Date(f.neededBy) - today) / 86400000);
}
const soon = daysLeft !== null && daysLeft <= 14;
const priority = serious && soon ? 'P1' : (serious || soon ? 'P2' : 'P3');
const reason = (serious ? f.impact : 'Improvement') + (daysLeft === null ? ', no deadline' : ', needed in ' + daysLeft + ' day(s)');
return [{ json: {
  requesterName: String(f.requesterName || '').trim(),
  requesterEmail: String(f.requesterEmail || '').trim(),
  department: String(f.department || '').trim(),
  title: String(f.title || '').trim(),
  description: String(f.description || '').trim().slice(0, 15000),
  impact: f.impact,
  neededBy: f.neededBy || 'Not given',
  priority, priorityReason: reason,
  routingTable: f.routingTable,
  existingRequests: existing,
  approverEmail: f.approverEmail
} }];

parameters.text:
=You are the intake analyst for a project team. Triage the request below for the PM.

1. requestType: one of Bug, Change request, New work, Support, Question.
2. summary: one plain sentence restating what is needed and why.
3. size: S (under a day), M (a few days), L (1-3 weeks), XL (more than 3 weeks or needs its own project). Give a one-line reason. If the description is too vague to size, say so in sizeReason and pick the most likely size.
4. routeTo: pick ONE owner from this routing table and explain why: {{ $json.routingTable }}
5. possibleDuplicateOf: if the request overlaps with one of the EXISTING REQUESTS, give its exact title. Otherwise an empty string.
6. missingInfo: questions the team needs answered before starting. Empty list if nothing is missing.
7. replyToRequester: a short, warm, professional email to {{ $json.requesterName }}: thank them, restate your understanding in one line, say it has been logged as priority {{ $json.priority }} and the PM will confirm next steps, and ask the missingInfo questions if any. NEVER promise a delivery date. Under 120 words. Sign off as "The project team".

Priority is already set by rules ({{ $json.priority }}: {{ $json.priorityReason }}). Do not change it.
Use only what is in the request. Never invent details.

REQUEST
From: {{ $json.requesterName }} ({{ $json.department || "department not given" }})
Title: {{ $json.title }}
Impact: {{ $json.impact }}
Needed by: {{ $json.neededBy }}
Description:
{{ $json.description }}

EXISTING REQUESTS:
{{ JSON.stringify($json.existingRequests) }}

